package com.tripnest.repository; import com.tripnest.entity.*; import org.springframework.data.jpa.repository.*; import org.springframework.data.repository.query.Param; import java.time.LocalDate; import java.util.*; public interface BookingRepository extends JpaRepository<Booking,Long>{@Query("select count(b) from Booking b where b.accommodation.id=:aid and b.status=com.tripnest.entity.BookingStatus.CONFIRMED and b.checkIn<:out and b.checkOut>:in") long overlap(@Param("aid") Long aid,@Param("in") LocalDate in,@Param("out") LocalDate out); @Query("select b from Booking b join fetch b.accommodation where b.user.id=:uid order by b.checkIn desc") List<Booking> byUser(@Param("uid") Long uid); @Query("select b from Booking b join fetch b.accommodation join fetch b.user order by b.createdAt desc") List<Booking> allDetailed(); Optional<Booking> findByReference(String reference); boolean existsByAccommodationId(Long id); long countByStatus(BookingStatus status); @Query("select count(b) from Booking b where b.status=com.tripnest.entity.BookingStatus.CONFIRMED and b.checkIn>=:today") long countUpcoming(@Param("today") LocalDate today); @Query("select coalesce(sum(b.totalAmount),0) from Booking b where b.status in (com.tripnest.entity.BookingStatus.CONFIRMED,com.tripnest.entity.BookingStatus.COMPLETED)") java.math.BigDecimal revenue(); @Query("select b.accommodation.city as city, count(b.id) as bookings from Booking b where b.status<>com.tripnest.entity.BookingStatus.CANCELLED group by b.accommodation.city order by count(b.id) desc") List<Object[]> topCities(org.springframework.data.domain.Pageable pageable);}
